#!/usr/bin/env bash

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SDLC_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"

SDLC_LIB="$SDLC_ROOT/scripts/lib"
[ ! -f "$SDLC_LIB/config.js" ] && { echo "ERROR: Could not locate scripts/lib/config.js. Is the Lift-SDLC plugin installed?" >&2; exit 2; }
node -e "
const { readSection } = require('$SDLC_LIB/config.js');
try {
  const advisory = require('$SDLC_LIB/context-advisory.js').getAdvisory({ skill: 'execute-plan-sdlc' });
  if (advisory) process.stderr.write(advisory + '\n');
} catch (_) { /* helper missing or sidecar unreadable — silent */ }
const execute = readSection(process.cwd(), 'execute');
console.log(JSON.stringify(execute?.guardrails || []));
"

#!/usr/bin/env bash
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SDLC_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"
LIB="$SDLC_ROOT/scripts/lib/openspec.js"
[ ! -f "$LIB" ] && { echo "ERROR: Could not locate openspec.js." >&2; exit 2; }
node -e "
const { validateChangeStrict } = require('$LIB');
const result = validateChangeStrict(process.cwd(), process.argv[1]);
console.log(JSON.stringify(result));
" "$1"

#!/usr/bin/env bash

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SDLC_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"

LIB="$SDLC_ROOT/scripts/lib/wave-summary.js"
[ ! -f "$LIB" ] && { echo "ERROR: Could not locate scripts/lib/wave-summary.js. Is the Lift-SDLC plugin installed?" >&2; exit 2; }
   [ -z "$LIB" ] && [ -f "plugins/lift-sdlc/scripts/lib/wave-summary.js" ] && LIB="plugins/lift-sdlc/scripts/lib/wave-summary.js"
   PARSE_RESULT=$(node -e "
   const { parseWaveSummary } = require('$LIB');
   const text = require('fs').readFileSync('/dev/stdin','utf8');
   const dispatched = JSON.parse(process.env.DISPATCHED_IDS || '[]');
   const r = parseWaveSummary(text, dispatched);
   process.stdout.write(JSON.stringify(r));
   " <<< "$WAVE_RUNNER_OUTPUT")

#!/usr/bin/env bash
set -e

if [ -z "$1" ]; then
  echo "Usage: $0 <file-path>" >&2
  exit 1
fi

if [ ! -f "$1" ]; then
  echo "Error: File '$1' not found" >&2
  exit 1
fi

node -e '
const fs = require("fs");
const crypto = require("crypto");
try {
  const content = fs.readFileSync(process.argv[1]);
  const hash = crypto.createHash("sha256").update(content).digest("hex");
  console.log(hash);
} catch (err) {
  console.error("Error hashing file:", err.message);
  process.exit(2);
}
' "$1"
